    50:/** The ruling must name a concrete, internally consistent outcome that fits the disputed charge. */
    51:function checkedResolution(output: JudgeOutput, input: AgentInput): Resolution {
    52:  const { action, amount, recipient, basis } = output.resolution;
    53:  if (action === 'no_action') {
    54:    if (amount !== 0 || recipient !== 'none') throw new Error('no_action must have amount 0 and recipient none');
    55:  } else {
    56:    if (amount <= 0 || recipient === 'none') throw new Error(`${action} needs a positive amount and a recipient`);
    57:    if (amount > disputedAmount(input) + 0.005) {
    58:      throw new Error(`${action} of ${amount} exceeds the disputed charge of ${disputedAmount(input)}`);
    59:    }
    60:  }
    61:  if (output.recommendation === 'inconclusive' && action !== 'no_action') {
    62:    throw new Error('An inconclusive ruling cannot move money');
    63:  }
    64:  return { action, amount, currency: currency(input), recipient, basis };
    65:}
