   140: "recommendationReasoning":"ruling with source-grounded explanation",
   141: "suggestedActions":["specific action including amount and recipient when justified"],
   142: "confidenceScore":"integer from 0 to 100", "confidenceReasoning":"uncertainties",
   143: "sourceRefs":["/existing/source/path"], "missingEvidence":["missing facts or unresolved conflicts"],
   144: "checklist":[{"id":"C1","finding":"what the record shows","conflict":false,"sourceRefs":["/existing/source/path"]}],
   145: "resolution":{"action":"full_refund|partial_refund|compensation|no_action","amount":0,"recipient":"rider|driver|none","basis":"calculation from policy and record"},
   146: "partyNotices":{"rider":"message to the rider","driver":"message to the driver"}
