   472:            <div className="flex gap-2">
   473:              <Button size="sm" disabled={pending || !reason.trim()} onClick={submit}>
   474:                {pending && <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" />} Submit decision
   475:              </Button>
   476:              <Button size="sm" variant="ghost" disabled={pending} onClick={() => setEditing(false)}>Cancel</Button>
   477:            </div>
   478:          </>
   479:        ) : existing ? (
