    25:/** Stable JSON-pointer paths into the original evidence (plus computed checks), without prior rulings. */
    26:export function sourceIndex(input: AgentInput): Record<string, unknown> {
    27:  const index: Record<string, unknown> = {};
    28:  function visit(value: unknown, path: string): void {
    29:    if (path) index[path] = value;
    30:    if (value !== null && typeof value === 'object') {
    31:      for (const [key, child] of Object.entries(value)) {
    32:        visit(child, path + '/' + key.replace(/~/g, '~0').replace(/\//g, '~1'));
    33:      }
    34:    }
    35:  }
    36:  visit({ ...originalRecord(input), ...computedSections(input) }, '');
    37:  return index;
    38:}
