    84:/** Parse a model's JSON answer, tolerating a ```json fence or a sentence around it. */
    85:export function parseJsonObject(text: string): unknown {
    86:  const trimmed = text.trim();
    87:  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    88:  const body = fenced ? fenced[1] : trimmed;
    89:  try {
    90:    return JSON.parse(body);
    91:  } catch (err) {
    92:    const start = body.indexOf('{');
    93:    const end = body.lastIndexOf('}');
    94:    if (start === -1 || end <= start) throw err;
    95:    return JSON.parse(body.slice(start, end + 1));
    96:  }
    97:}
