{"requestId":"d4f4b0ecc3784251a5136cf2ddb49c55","modelId":"default-model","modelName":"Auto","isHelperMessage":false,"traceId":"15687fc3d70870751fa711bbb8d2eee0","toolStatus":{"call_b6fbb412201b4169a164bbae":{"ready":true,"status":"executed","args":{"filePath":"/Users/junyuli/Projects/MITB_Sem1/Tencent_Cloud_Captain_Dragonfly/dispute-review-agent/backend/src/modules/dispute/agents/orchestrator.ts"},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"/Users/junyuli/Projects/MITB_Sem1/Tencent_Cloud_Captain_Dragonfly/dispute-review-agent/backend/src/modules/dispute/agents/orchestrator.ts","content":"     1:import { Annotation, END, START, StateGraph } from '@langchain/langgraph';
     2:import type {
     3:  AdvocateCase,
     4:  AgentInput,
     5:  EscalationDecision,
     6:  EvidenceValidation,
     7:  JudgeReview,
     8:  MultiAgentReview,
     9:  PriorityAssessment,
    10:  ReviewWorkflowStatus,
    11:} from './contracts';
    12:import { runDriverAdvocate } from './driver-advocate';
    13:import { runEscalationAgent } from './escalation-agent';
    14:import { runEvidenceValidationAgent } from './evidence-validation-agent';
    15:import { runJudge } from './judge';
    16:import { runPrioritizationAgent } from './prioritization-agent';
    17:import { runRiderAdvocate } from './rider-advocate';
    18:import { disputeId, validateInput } from './shared';
    19:import { disputeType } from './checklist';
    20:import { precedentStore } from '../precedents';
    21:
    22:const ReviewState = Annotation.Root({
    23:  input: Annotation<AgentInput>(),
    24:  priorityAssessment: Annotation<PriorityAssessment>(),
    25:  evidenceValidation: Annotation<EvidenceValidation>(),
    26:  rider: Annotation<AdvocateCase>(),
    27:  driver: Annotation<AdvocateCase>(),
    28:  ruling: Annotation<JudgeReview>(),
    29:  escalation: Annotation<EscalationDecision>(),
    30:  workflowStatus: Annotation<ReviewWorkflowStatus>(),
    31:});
    32:
    33:/**
    34: * LangGraph workflow: priority -> evidence validation -> parallel advocates ->
    35: * Judge -> confidence routing -> automatic resolution or human intervention.
    36: */
    37:export const disputeReviewGraph = new StateGraph(ReviewState)
    38:  .addNode('prioritization', (state) => ({
    39:    priorityAssessment: runPrioritizationAgent(state.input),
    40:  }))
    41:  .addNode('evidence_validation', (state) => ({
    42:    evidenceValidation: runEvidenceValidationAgent(state.input),
    43:  }))
    44:  .addNode('rider_advocate', async (state) => ({
    45:    rider: await runRiderAdvocate(state.input),
    46:  }))
    47:  .addNode('driver_advocate', async (state) => ({
    48:    driver: await runDriverAdvocate(state.input),
    49:  }))
    50:  .addNode('judge', async (state) => ({
    51:    ruling: await runJudge(
    52:      state.input,
    53:      state.rider,
    54:      state.driver,
    55:      precedentStore.select(disputeType(state.input), disputeId(state.input))
    56:    ),
    57:  }))
    58:  .addNode('confidence_escalation', (state) => ({
    59:    escalation: runEscalationAgent(state.ruling),
    60:  }))
    61:  .addNode('automatic_resolution', () => ({
    62:    workflowStatus: 'auto_resolved' as const,
    63:  }))
    64:  .addNode('human_intervention', () => ({
    65:    workflowStatus: 'human_intervention_required' as const,
    66:  }))
    67:  .addEdge(START, 'prioritization')
    68:  .addEdge('prioritization', 'evidence_validation')
    69:  .addEdge('evidence_validation', 'rider_advocate')
    70:  .addEdge('evidence_validation', 'driver_advocate')
    71:  .addEdge(['rider_advocate', 'driver_advocate'], 'judge')
    72:  .addEdge('judge', 'confidence_escalation')
    73:  .addConditionalEdges(
    74:    'confidence_escalation',
    75:    (state) => state.escalation.needsHuman ? 'human' : 'automatic',
    76:    { human: 'human_intervention', automatic: 'automatic_resolution' }
    77:  )
    78:  .addEdge('automatic_resolution', END)
    79:  .addEdge('human_intervention', END)
    80:  .compile();
    81:
    82:export async function reviewDispute(input: AgentInput): Promise<MultiAgentReview> {
    83:  const state = await disputeReviewGraph.invoke({ input: validateInput(input) });
    84:  if (!state.ruling || !state.rider || !state.driver || !state.priorityAssessment ||
    85:      !state.evidenceValidation || !state.escalation || !state.workflowStatus) {
    86:    throw new Error('LangGraph review finished without a complete workflow state.');
    87:  }
    88:  return {
    89:    ...state.ruling,
    90:    advocateSubmissions: { rider: state.rider, driver: state.driver },
    91:    priorityAssessment: state.priorityAssessment,
    92:    evidenceValidation: state.evidenceValidation,
    93:    escalation: state.escalation,
    94:    workflowStatus: state.workflowStatus,
    95:  };
    96:}
