{"requestId":"d4f4b0ecc3784251a5136cf2ddb49c55","modelId":"default-model","modelName":"Auto","isHelperMessage":false,"traceId":"15687fc3d70870751fa711bbb8d2eee0","toolStatus":{"call_e83cd8f68bf24b52b3f3f626":{"ready":true,"status":"executed","args":{"filePath":"/Users/junyuli/Projects/MITB_Sem1/Tencent_Cloud_Captain_Dragonfly/dispute-review-agent/backend/src/modules/dispute/agents/evidence-validation-agent.ts"},"result":{"status":"success","success":true,"result":{"type":"read_file_result","path":"/Users/junyuli/Projects/MITB_Sem1/Tencent_Cloud_Captain_Dragonfly/dispute-review-agent/backend/src/modules/dispute/agents/evidence-validation-agent.ts","content":"     1:import type { AgentInput, EvidenceValidation } from './contracts';
     2:import { isNoShowDataset, isRouteDeviationDataset } from './dataset';
     3:import { analyzeRoute } from './route-analysis';
     4:import { validateInput } from './shared';
     5:
     6:/** Checks structural usability before the advocates run. Limited evidence is surfaced, not hidden. */
     7:export function runEvidenceValidationAgent(input: AgentInput): EvidenceValidation {
     8:  const record = validateInput(input);
     9:  const checks: string[] = ['Record schema and linked party/trip identifiers are valid.'];
    10:  const warnings: string[] = [];
    11:  let evidenceItemCount = 0;
    12:
    13:  if ('dispute_ticket' in record) {
    14:    evidenceItemCount = record.gps_telemetry.length + record.chat_logs.length + record.app_events.length;
    15:    if (record.gps_telemetry.length === 0) warnings.push('No GPS telemetry was supplied.');
    16:    if (record.chat_logs.length === 0) warnings.push('No chat or call records were supplied.');
    17:    if (record.app_events.length === 0) warnings.push('No app event records were supplied.');
    18:  }
    19:
    20:  if (isRouteDeviationDataset(record)) {
    21:    checks.push('GPS telemetry, recommended route, fare breakdown, chat logs, app events, and fare policy are available to cite.');
    22:    const analysis = analyzeRoute(record);
    23:    checks.push(...analysis.findings);
    24:    if (analysis.exceeds_tolerance) {
    25:      warnings.push(`Route is ${analysis.deviation_pct}% longer than recommended, above the ${analysis.tolerance_pct}% policy tolerance.`);
    26:    }
    27:    if (analysis.unexpected_stops.length) warnings.push(`${analysis.unexpected_stops.length} unexplained mid-trip stop(s) in the GPS track.`);
    28:    if (!analysis.breakdown_matches_total || !analysis.total_matches_final_fare) {
    29:      warnings.push('The fare breakdown does not reconcile with the charged fare.');
    30:    }
    31:  } else if (isNoShowDataset(record)) {
    32:    checks.push('GPS telemetry, chat logs, app events, and cancellation policy are available to cite.');
    33:    if (record.trip_data.driver_wait_start !== record.trip_data.driver_arrival_time) {
    34:      warnings.push('Driver arrival and recorded wait-start timestamps differ.');
    35:    }
    36:    const timerStart = record.app_events.find((event) => event.event_type === 'wait_timer_started');
    37:    if (timerStart && timerStart.timestamp !== record.trip_data.driver_wait_start) {
    38:      warnings.push('The app wait-timer event conflicts with the trip wait-start timestamp.');
    39:    }
    40:  } else {
    41:    evidenceItemCount = record.evidence.length;
    42:    checks.push('Case parties, trip information, and evidence entries are structurally available.');
    43:    if (record.evidence.length === 0) warnings.push('No supporting evidence has been uploaded.');
    44:    if (!record.evidence.some((item) => item.party === 'platform')) {
    45:      warnings.push('No independent platform record is present.');
    46:    }
    47:    if (!record.driver.statement.trim()) warnings.push('Driver statement is missing.');
    48:    if (!record.passenger.statement.trim()) warnings.push('Rider statement is missing.');
    49:  }
    50:
    51:  return {
    52:    agent: 'evidence_validation_agent',
    53:    status: evidenceItemCount > 0 ? 'ready' : 'limited',
    54:    evidenceItemCount,
    55:    checks,
    56:    warnings,
    57:    validatedAt: new Date().toISOString(),
    58:  };
    59:}
