    35:
    36:/** GPS points further than this from the recommended route count as off-route. */
    37:export const OFF_ROUTE_M = 500;
    38:const EARTH_M = 6_371_000;
    39:const CENT = 0.01;
    40:
    41:const round = (n: number, places = 1) => Math.round(n * 10 ** places) / 10 ** places;
    42:const money = (n: number) => round(n, 2);
    43:const minutesBetween = (a: string, b: string) => (Date.parse(b) - Date.parse(a)) / 60_000;
    44:
    45:type Point = { lat: number; lng: number };
    46:
    47:function haversineM(a: Point, b: Point): number {
    48:  const rad = Math.PI / 180;
    49:  const dLat = (b.lat - a.lat) * rad;
    50:  const dLng = (b.lng - a.lng) * rad;
    51:  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
    52:  return 2 * EARTH_M * Math.asin(Math.sqrt(h));
    53:}
    54:
    55:/** Distance from p to segment ab, on a local flat projection (fine at city scale). */
    56:function pointToSegmentM(p: Point, a: Point, b: Point): number {
    57:  const kx = Math.cos(p.lat * Math.PI / 180) * EARTH_M * Math.PI / 180;
    58:  const ky = EARTH_M * Math.PI / 180;
    59:  const [px, py] = [p.lng * kx, p.lat * ky];
    60:  const [ax, ay] = [a.lng * kx, a.lat * ky];
    61:  const [bx, by] = [b.lng * kx, b.lat * ky];
    62:  const [dx, dy] = [bx - ax, by - ay];
    63:  const len2 = dx * dx + dy * dy;
    64:  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / len2));
    65:  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
    66:}
    67:
    68:function distanceToRouteM(p: Point, route: Point[]): number {
    69:  let best = Infinity;
    70:  for (let i = 1; i < route.length; i++) best = Math.min(best, pointToSegmentM(p, route[i - 1], route[i]));
    71:  return best;
    72:}
    73:
    74:export function analyzeRoute(data: RouteDeviationDataset): RouteAnalysis {
    75:  const trip = data.trip_data;
    76:  const route = data.recommended_route;
    77:  const fb = trip.fare_breakdown;
    78:  const start = Date.parse(trip.pickup_time);
    79:  const end = Date.parse(trip.dropoff_time);
    80:
    81:  // Only points recorded during the trip, keeping their index for citations
    82:  const points = data.gps_telemetry
    83:    .map((p, i) => ({ ...p, ref: `/gps_telemetry/${i}` }))
    84:    .filter((p) => Date.parse(p.timestamp) >= start && Date.parse(p.timestamp) <= end);
    85:
    86:  let pathM = 0;
    87:  for (let i = 1; i < points.length; i++) pathM += haversineM(points[i - 1], points[i]);
    88:
    89:  const offsets = points.map((p) => ({ ref: p.ref, m: distanceToRouteM(p, route.waypoints) }));
    90:  const offRoute = offsets.filter((o) => o.m > OFF_ROUTE_M);
    91:
    92:  // Stationary runs between pickup and drop-off (the first and last points are the stops themselves)
    93:  const stops: RouteAnalysis['unexpected_stops'] = [];
    94:  let run: typeof points = [];
    95:  const flush = () => {
    96:    if (run.length) stops.push({
    97:      from: run[0].timestamp, to: run[run.length - 1].timestamp,
    98:      minutes: round(minutesBetween(run[0].timestamp, run[run.length - 1].timestamp)),
    99:      points: run.map((p) => p.ref),
   100:    });
   101:    run = [];
   102:  };
   103:  for (const p of points.slice(1, -1)) {
   104:    if (p.speed_kmh === 0) run.push(p);
   105:    else flush();
   106:  }
   107:  flush();
   108:
   109:  const extraKm = trip.actual_distance_km - route.distance_km;
   110:  const deviationPct = (extraKm / route.distance_km) * 100;
   111:  const actualMin = minutesBetween(trip.pickup_time, trip.dropoff_time);
   112:  const fareDiff = trip.final_fare - trip.estimated_fare;
   113:  const computedTotal = (fb.base_fare + fb.distance_fare + fb.time_fare) * fb.surge_multiplier
   114:    + fb.booking_fee - fb.promo_discount;
   115:  const breakdownOk = Math.abs(computedTotal - fb.total) < CENT;
   116:  const totalOk = Math.abs(fb.total - trip.final_fare) < CENT;
   117:  const tolerance = data.fare_policy.deviation_tolerance_pct;
   118:
   119:  const findings = [
   120:    `Metered distance ${trip.actual_distance_km} km vs recommended ${route.distance_km} km ` +
   121:      `(${extraKm >= 0 ? '+' : ''}${round(extraKm)} km, ${round(deviationPct)}%; policy tolerance ${tolerance}%).`,
   122:    offRoute.length
   123:      ? `${offRoute.length} of ${points.length} trip GPS points are more than ${OFF_ROUTE_M} m from the recommended route ` +
   124:        `(max ${Math.round(Math.max(...offsets.map((o) => o.m)))} m).`
   125:      : `All ${points.length} trip GPS points are within ${OFF_ROUTE_M} m of the recommended route.`,
   126:    `Trip took ${round(actualMin)} min vs ${trip.estimated_duration_min} min estimated.`,
   127:    ...stops.map((s) => `Stationary mid-trip from ${s.from} to ${s.to} (${s.minutes} min).`),
   128:    `Final fare ${money(trip.final_fare)} vs upfront estimate ${money(trip.estimated_fare)} ` +
   129:      `(${fareDiff >= 0 ? '+' : ''}${money(fareDiff)}).`,
   130:  ];
   131:  if (!breakdownOk) findings.push(`Fare components add up to ${money(computedTotal)}, not the stated total ${money(fb.total)}.`);
   132:  if (!totalOk) findings.push(`Breakdown total ${money(fb.total)} differs from the charged fare ${money(trip.final_fare)}.`);
   133:  if (fb.surge_multiplier > 1) findings.push(`Surge multiplier ${fb.surge_multiplier} applied.`);
   134:  if (fb.promo_code) findings.push(`Promo code ${fb.promo_code} applied (discount ${money(fb.promo_discount)}).`);
   135:
   136:  return {
   137:    recommended_distance_km: route.distance_km,
   138:    actual_distance_km: trip.actual_distance_km,
   139:    extra_distance_km: round(extraKm),
   140:    deviation_pct: round(deviationPct),
   141:    tolerance_pct: tolerance,
   142:    exceeds_tolerance: deviationPct > tolerance,
   143:    gps_path_distance_km: round(pathM / 1000),
   144:    max_off_route_m: offsets.length ? Math.round(Math.max(...offsets.map((o) => o.m))) : 0,
   145:    off_route_points: offRoute.length,
   146:    first_off_route_point: offRoute[0]?.ref ?? null,
   147:    estimated_duration_min: trip.estimated_duration_min,
   148:    actual_duration_min: round(actualMin),
   149:    extra_duration_min: round(actualMin - trip.estimated_duration_min),
   150:    unexpected_stops: stops,
   151:    estimated_fare: money(trip.estimated_fare),
   152:    final_fare: money(trip.final_fare),
   153:    fare_difference: money(fareDiff),
   154:    fare_difference_pct: trip.estimated_fare > 0 ? round((fareDiff / trip.estimated_fare) * 100) : 0,
   155:    breakdown_computed_total: money(computedTotal),
   156:    breakdown_matches_total: breakdownOk,
   157:    total_matches_final_fare: totalOk,
   158:    findings,
   159:  };
   160:}
