    50:/** The ruling must name a concrete, internally consistent outcome that fits the disputed charge. */
    51:function checkedResolution(output: JudgeOutput, input: AgentInput): Resolution {
    52:  const { action, amount, recipient, basis } = output.resolution;
    53:  if (action === 'no_action') {
    54:    if (amount !== 0 || recipient !== 'none') throw new Error('no_action must have amount 0 and recipient none');
