    56:    if (amount <= 0 || recipient === 'none') throw new Error(`${action} needs a positive amount and a recipient`);
    57:    if (amount > disputedAmount(input) + 0.005) {
    58:      throw new Error(`${action} of ${amount} exceeds the disputed charge of ${disputedAmount(input)}`);
    59:    }
