    37:/** GPS points further than this from the recommended route count as off-route. */
    38:export const OFF_ROUTE_M = 500;
    39:/** Speed below this (km/h) counts as stationary, tolerating GPS jitter. */
    40:const STOP_SPEED_KMH = 1;
    41:/** Stops shorter than this (minutes) are likely GPS noise and are filtered out. */
    42:const MIN_STOP_MIN = 1;
    43:const EARTH_M = 6_371_000;
    44:const CENT = 0.01;
    45:
    46:const round = (n: number, places = 1) => Math.round(n * 10 ** places) / 10 ** places;
    47:const money = (n: number) => round(n, 2);
    48:const minutesBetween = (a: string, b: string) => (Date.parse(b) - Date.parse(a)) / 60_000;
    49:
    50:type Point = { lat: number; lng: number };
    51:
    52:function haversineM(a: Point, b: Point): number {
    53:  const rad = Math.PI / 180;
    54:  const dLat = (b.lat - a.lat) * rad;
    55:  const dLng = (b.lng - a.lng) * rad;
    56:  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
    57:  return 2 * EARTH_M * Math.asin(Math.sqrt(h));
