    59:
    60:/** Distance from p to segment ab, on a local flat projection (fine at city scale). */
    61:function pointToSegmentM(p: Point, a: Point, b: Point): number {
    62:  const kx = Math.cos(p.lat * Math.PI / 180) * EARTH_M * Math.PI / 180;
    63:  const ky = EARTH_M * Math.PI / 180;
    64:  const [px, py] = [p.lng * kx, p.lat * ky];
    65:  const [ax, ay] = [a.lng * kx, a.lat * ky];
    66:  const [bx, by] = [b.lng * kx, b.lat * ky];
    67:  const [dx, dy] = [bx - ax, by - ay];
    68:  const len2 = dx * dx + dy * dy;
    69:  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / len2));
    70:  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
    71:}
