    73:function distanceToRouteM(p: Point, route: Point[]): number {
    74:  let best = Infinity;
    75:  for (let i = 1; i < route.length; i++) best = Math.min(best, pointToSegmentM(p, route[i - 1], route[i]));
    76:  return best;
    77:}
