    81:  const route = data.recommended_route;
    82:  const fb = trip.fare_breakdown;
    83:  const start = Date.parse(trip.pickup_time);
    84:  const end = Date.parse(trip.dropoff_time);
    85:
    86:  // Only points recorded during the trip, keeping their index for citations
    87:  const points = data.gps_telemetry
    88:    .map((p, i) => ({ ...p, ref: `/gps_telemetry/${i}` }))
    89:    .filter((p) => Date.parse(p.timestamp) >= start && Date.parse(p.timestamp) <= end);
