    96:
    97:  // Stationary runs between pickup and drop-off (the first and last points are the stops themselves).
    98:  // A speed threshold tolerates GPS jitter; brief blips below MIN_STOP_MIN are filtered as noise.
    99:  const stops: RouteAnalysis['unexpected_stops'] = [];
   100:  let run: typeof points = [];
   101:  const flush = () => {
   102:    if (run.length) {
   103:      const minutes = round(minutesBetween(run[0].timestamp, run[run.length - 1].timestamp));
   104:      if (minutes >= MIN_STOP_MIN) stops.push({
   105:        from: run[0].timestamp, to: run[run.length - 1].timestamp,
   106:        minutes,
   107:        points: run.map((p) => p.ref),
   108:      });
   109:    }
   110:    run = [];
   111:  };
   112:  for (const p of points.slice(1, -1)) {
   113:    if (p.speed_kmh < STOP_SPEED_KMH) run.push(p);
   114:    else flush();
   115:  }
   116:  flush();
   117:
   118:  const extraKm = trip.actual_distance_km - route.distance_km;
   119:  const deviationPct = (extraKm / route.distance_km) * 100;
   120:  const actualMin = minutesBetween(trip.pickup_time, trip.dropoff_time);
   121:  const fareDiff = trip.final_fare - trip.estimated_fare;
   122:  const computedTotal = (fb.base_fare + fb.distance_fare + fb.time_fare) * fb.surge_multiplier
   123:    + fb.booking_fee - fb.promo_discount;
   124:  const breakdownOk = Math.abs(computedTotal - fb.total) < CENT;
   125:  const totalOk = Math.abs(fb.total - trip.final_fare) < CENT;
   126:  const tolerance = data.fare_policy.deviation_tolerance_pct;
   127:  const gpsPathKm = round(pathM / 1000);
   128:
   129:  const findings: string[] = [];
   130:
   131:  if (points.length === 0) {
   132:    findings.push('No GPS points were recorded during the trip window (pickup to drop-off).');
   133:  } else {
   134:    findings.push(
   135:      `Metered distance ${trip.actual_distance_km} km vs recommended ${route.distance_km} km ` +
   136:        `(${extraKm >= 0 ? '+' : ''}${round(extraKm)} km, ${round(deviationPct)}%; policy tolerance ${tolerance}%).`
   137:    );
   138:    findings.push(
   139:      offRoute.length
   140:        ? `${offRoute.length} of ${points.length} trip GPS points are more than ${OFF_ROUTE_M} m from the recommended route ` +
   141:          `(max ${Math.round(Math.max(...offsets.map((o) => o.m)))} m).`
   142:        : `All ${points.length} trip GPS points are within ${OFF_ROUTE_M} m of the recommended route.`
   143:    );
