   147:        `GPS path distance ${gpsPathKm} km differs materially from the metered distance ${trip.actual_distance_km} km, ` +
   148:        `which may indicate a metering issue or GPS gaps.`
   149:      );
   150:    }
   151:    findings.push(`Trip took ${round(actualMin)} min vs ${trip.estimated_duration_min} min estimated.`);
   152:    findings.push(...stops.map((s) => `Stationary mid-trip from ${s.from} to ${s.to} (${s.minutes} min).`));
   153:    findings.push(
   154:      `Final fare ${money(trip.final_fare)} vs upfront estimate ${money(trip.estimated_fare)} ` +
   155:        `(${fareDiff >= 0 ? '+' : ''}${money(fareDiff)}).`
   156:    );
   157:  }
   158:  if (!breakdownOk) findings.push(`Fare components add up to ${money(computedTotal)}, not the stated total ${money(fb.total)}.`);
   159:  if (!totalOk) findings.push(`Breakdown total ${money(fb.total)} differs from the charged fare ${money(trip.final_fare)}.`);
   160:  if (fb.surge_multiplier > 1) findings.push(`Surge multiplier ${fb.surge_multiplier} applied.`);
   161:  if (fb.promo_code) findings.push(`Promo code ${fb.promo_code} applied (discount ${money(fb.promo_discount)}).`);
   162:
   163:  return {
   164:    recommended_distance_km: route.distance_km,
   165:    actual_distance_km: trip.actual_distance_km,
   166:    extra_distance_km: round(extraKm),
   167:    deviation_pct: round(deviationPct),
   168:    tolerance_pct: tolerance,
   169:    exceeds_tolerance: deviationPct > tolerance,
   170:    gps_path_distance_km: gpsPathKm,
   171:    max_off_route_m: offsets.length ? Math.round(Math.max(...offsets.map((o) => o.m))) : 0,
   172:    off_route_points: offRoute.length,
   173:    first_off_route_point: offRoute[0]?.ref ?? null,
   174:    estimated_duration_min: trip.estimated_duration_min,
   175:    actual_duration_min: round(actualMin),
   176:    extra_duration_min: round(actualMin - trip.estimated_duration_min),
   177:    unexpected_stops: stops,
   178:    estimated_fare: money(trip.estimated_fare),
   179:    final_fare: money(trip.final_fare),
   180:    fare_difference: money(fareDiff),
   181:    fare_difference_pct: trip.estimated_fare > 0 ? round((fareDiff / trip.estimated_fare) * 100) : null,
   182:    breakdown_computed_total: money(computedTotal),
   183:    breakdown_matches_total: breakdownOk,
   184:    total_matches_final_fare: totalOk,
   185:    findings,
   186:  };
