   196:export const disputeStore = {
   197:  getAll(): DisputeCase[] {
   198:    const priorityRank = { urgent: 4, high: 3, medium: 2, low: 1 };
   199:    return [...cases].sort(
   200:      (a, b) =>
   201:        priorityRank[b.priority] - priorityRank[a.priority] ||
   202:        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
   203:    );
   204:  },
   205:
   206:  getById(id: string): DisputeCase | undefined {
   207:    return cases.find((c) => c.id === id);
   208:  },
   209:
   210:  create(
   211:    dto: CreateDisputeDTO,
   212:    opts: { caseNumber?: string; dataset?: SampleDataset; createdAt?: string } = {}
   213:  ): DisputeCase {
   214:    const now = new Date().toISOString();
   215:    const newCase: DisputeCase = {
   216:      id: generateId(),
   217:      caseNumber: opts.caseNumber ?? generateCaseNumber(),
   218:      status: 'pending',
   219:      priority: dto.priority,
   220:      type: dto.type,
   221:      title: dto.title,
   222:      createdAt: opts.createdAt ?? now,
   223:      updatedAt: now,
   224:      driver: dto.driver,
   225:      passenger: dto.passenger,
   226:      trip: dto.trip,
   227:      evidence: dto.evidence.map((e) => makeEvidence(e)),
   228:      dataset: opts.dataset,
   229:    };
   230:    cases.push(newCase);
   231:    return newCase;
   232:  },
   233:
   234:  addEvidence(id: string, input: NewEvidence): DisputeCase | undefined {
   235:    const c = cases.find((c) => c.id === id);
   236:    if (!c) return undefined;
   237:    c.evidence.push(makeEvidence(input));
   238:    c.updatedAt = new Date().toISOString();
   239:    return c;
   240:  },
   241:
   242:  updateReview(id: string, review: DisputeCase['review']): DisputeCase | undefined {
   243:    const c = cases.find((c) => c.id === id);
   244:    if (!c || !review) return undefined;
   245:    c.review = review;
   246:    if (review.priorityAssessment) {
   247:      c.priorityAssessment = review.priorityAssessment;
   248:      c.priority = review.priorityAssessment.priority;
   249:    }
   250:    // A human decision stands: retain the new AI result for reference without
   251:    // reopening the case or discarding either feedback mechanism.
   252:    if (c.humanOverride) {
   253:      c.status = 'resolved';
   254:      c.updatedAt = new Date().toISOString();
   255:      return c;
   256:    }
   257:    c.learningFeedback = undefined;
   258:    const failed = review.mode === 'fallback';
   259:    if (failed) {
   260:      // Review could not run: stay open for a retry, nothing to escalate
   261:      c.escalation = review.escalation ?? {
   262:        needsHuman: false,
   263:        reason: 'AI review did not complete. Retry the review.',
   264:      };
   265:      c.status = 'pending';
   266:    } else if (review.escalation?.needsHuman) {
   267:      c.escalation = review.escalation;
   268:      c.status = 'under_review';
   269:    } else {
   270:      c.escalation = review.escalation ?? { needsHuman: false, reason: '' };
   271:      c.status = 'resolved';
   272:    }
   273:    c.updatedAt = new Date().toISOString();
   274:    return c;
   275:  },
   276:
   277:  /** A human reviewer's decision; closes the case and records it for later learning. */
   278:  override(
   279:    id: string,
   280:    decision: {
   281:      recommendation: Recommendation;
   282:      reason: string;
   283:      decidedBy?: string;
   284:      useAsPrecedent: boolean;
   285:    }
   286:  ): DisputeCase | undefined {
   287:    const c = cases.find((c) => c.id === id);
   288:    if (!c) return undefined;
   289:    const now = new Date().toISOString();
   290:    c.humanOverride = { ...decision, decidedAt: now };
   291:    c.escalation = { needsHuman: false, reason: 'Resolved by a human reviewer.' };
   292:    c.status = 'resolved';
   293:    c.updatedAt = now;
   294:    if (decision.useAsPrecedent) precedentStore.upsert(precedentFromCase(c, c.humanOverride));
   295:    else precedentStore.remove(c.caseNumber);
   296:    return c;
   297:  },
   298:
   299:  /** Withdraws a human decision and restores the status implied by the AI result. */
   300:  clearOverride(id: string): DisputeCase | undefined {
   301:    const c = cases.find((item) => item.id === id);
   302:    if (!c) return undefined;
   303:    if (!c.humanOverride) return c;
   304:    c.humanOverride = undefined;
   305:    c.learningFeedback = undefined;
   306:    precedentStore.remove(c.caseNumber);
   307:    if (c.review) return this.updateReview(id, c.review);
   308:    c.escalation = undefined;
   309:    c.status = 'pending';
   310:    c.updatedAt = new Date().toISOString();
   311:    return c;
   312:  },
   313:
   314:  /** A deleted precedent remains a decision, but no longer teaches the Judge. */
   315:  unmarkPrecedent(caseNumber: string): void {
   316:    const c = cases.find((item) => item.caseNumber === caseNumber);
   317:    if (c?.humanOverride) c.humanOverride.useAsPrecedent = false;
   318:  },
   319:
   320:  setPriorityAssessment(id: string, assessment: PriorityAssessment): DisputeCase | undefined {
   321:    const c = cases.find((item) => item.id === id);
   322:    if (!c) return undefined;
   323:    c.priorityAssessment = assessment;
   324:    c.priority = assessment.priority;
   325:    c.updatedAt = new Date().toISOString();
   326:    return c;
   327:  },
   328:
   329:  setLearningFeedback(id: string, feedback: LearningFeedback): DisputeCase | undefined {
   330:    const c = cases.find((item) => item.id === id);
   331:    if (!c) return undefined;
   332:    c.learningFeedback = feedback;
