     3:/**
     4: * Deterministic telemetry checks for route-deviation disputes, computed from the
     5: * record itself (no model call). The agents receive the result as
     6: * /computed_route_analysis/... so they cite measured numbers instead of
     7: * estimating distances from raw coordinates.
     8: */
     9:export interface RouteAnalysis {
    10:  recommended_distance_km: number;
    11:  actual_distance_km: number;
    12:  extra_distance_km: number;
    13:  deviation_pct: number;
    14:  tolerance_pct: number;
    15:  exceeds_tolerance: boolean;
    16:  gps_path_distance_km: number;
    17:  max_off_route_m: number;
    18:  off_route_points: number;
    19:  /** JSON pointer to the first GPS point more than OFF_ROUTE_M from the recommended route */
    20:  first_off_route_point: string | null;
    21:  estimated_duration_min: number;
    22:  actual_duration_min: number;
    23:  extra_duration_min: number;
    24:  unexpected_stops: { from: string; to: string; minutes: number; points: string[] }[];
    25:  estimated_fare: number;
    26:  final_fare: number;
    27:  fare_difference: number;
    28:  /** Percentage difference from the upfront estimate; null when the estimate is zero. */
    29:  fare_difference_pct: number | null;
    30:  /** (base + distance + time) x surge + booking fee - promo discount */
    31:  breakdown_computed_total: number;
    32:  breakdown_matches_total: boolean;
    33:  total_matches_final_fare: boolean;
    34:  findings: string[];
    35:}
    36:
    37:/** GPS points further than this from the recommended route count as off-route. */
    38:export const OFF_ROUTE_M = 500;
    39:/** Speed below this (km/h) counts as stationary, tolerating GPS jitter. */
    40:const STOP_SPEED_KMH = 1;
    41:/** Stops shorter than this (minutes) are likely GPS noise and are filtered out. */
    42:const MIN_STOP_MIN = 1;
    43:const EARTH_M = 6_371_000;
    44:const CENT = 0.01;
    45:
    46:const round = (n: number, places = 1) => Math.round(n * 10 ** places) / 10 ** places;
    47:const money = (n: number) => round(n, 2);
    48:const minutesBetween = (a: string, b: string) => (Date.parse(b) - Date.parse(a)) / 60_000;
    49:
    50:type Point = { lat: number; lng: number };
    51:
    52:function haversineM(a: Point, b: Point): number {
    53:  const rad = Math.PI / 180;
    54:  const dLat = (b.lat - a.lat) * rad;
    55:  const dLng = (b.lng - a.lng) * rad;
    56:  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
    57:  return 2 * EARTH_M * Math.asin(Math.sqrt(h));
    58:}
    59:
    60:/** Distance from p to segment ab, on a local flat projection (fine at city scale). */
    61:function pointToSegmentM(p: Point, a: Point, b: Point): number {
    62:  const kx = Math.cos(p.lat * Math.PI / 180) * EARTH_M * Math.PI / 180;
    63:  const ky = EARTH_M * Math.PI / 180;
    64:  const [px, py] = [p.lng * kx, p.lat * ky];
    65:  const [ax, ay] = [a.lng * kx, a.lat * ky];
    66:  const [bx, by] = [b.lng * kx, b.lat * ky];
    67:  const [dx, dy] = [bx - ax, by - ay];
    68:  const len2 = dx * dx + dy * dy;
    69:  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / len2));
    70:  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
    71:}
    72:
    73:function distanceToRouteM(p: Point, route: Point[]): number {
    74:  let best = Infinity;
    75:  for (let i = 1; i < route.length; i++) best = Math.min(best, pointToSegmentM(p, route[i - 1], route[i]));
    76:  return best;
    77:}
    78:
    79:export function analyzeRoute(data: RouteDeviationDataset): RouteAnalysis {
    80:  const trip = data.trip_data;
    81:  const route = data.recommended_route;
    82:  const fb = trip.fare_breakdown;
    83:  const start = Date.parse(trip.pickup_time);
    84:  const end = Date.parse(trip.dropoff_time);
    85:
    86:  // Only points recorded during the trip, keeping their index for citations
    87:  const points = data.gps_telemetry
    88:    .map((p, i) => ({ ...p, ref: `/gps_telemetry/${i}` }))
    89:    .filter((p) => Date.parse(p.timestamp) >= start && Date.parse(p.timestamp) <= end);
    90:
    91:  let pathM = 0;
    92:  for (let i = 1; i < points.length; i++) pathM += haversineM(points[i - 1], points[i]);
    93:
    94:  const offsets = points.map((p) => ({ ref: p.ref, m: distanceToRouteM(p, route.waypoints) }));
    95:  const offRoute = offsets.filter((o) => o.m > OFF_ROUTE_M);
    96:
    97:  // Stationary runs between pickup and drop-off (the first and last points are the stops themselves).
    98:  // A speed threshold tolerates GPS jitter; brief blips below MIN_STOP_MIN are filtered as noise.
    99:  const stops: RouteAnalysis['unexpected_stops'] = [];
   100:  let run: typeof points = [];
   101:  const flush = () => {
   102:    if (run.length) {
   103:      const minutes = round(minutesBetween(run[0].timestamp, run[run.length - 1].timestamp));
   104:      if (minutes >= MIN_STOP_MIN) stops.push({
   105:        from: run[0].timestamp, to: run[run.length - 1].timestamp,
   106:        minutes,
   107:        points: run.map((p) => p.ref),
   108:      });
   109:    }
   110:    run = [];
   111:  };
   112:  for (const p of points.slice(1, -1)) {
   113:    if (p.speed_kmh < STOP_SPEED_KMH) run.push(p);
   114:    else flush();
   115:  }
   116:  flush();
   117:
   118:  const extraKm = trip.actual_distance_km - route.distance_km;
   119:  const deviationPct = (extraKm / route.distance_km) * 100;
   120:  const actualMin = minutesBetween(trip.pickup_time, trip.dropoff_time);
   121:  const fareDiff = trip.final_fare - trip.estimated_fare;
   122:  const computedTotal = (fb.base_fare + fb.distance_fare + fb.time_fare) * fb.surge_multiplier
   123:    + fb.booking_fee - fb.promo_discount;
   124:  const breakdownOk = Math.abs(computedTotal - fb.total) < CENT;
   125:  const totalOk = Math.abs(fb.total - trip.final_fare) < CENT;
   126:  const tolerance = data.fare_policy.deviation_tolerance_pct;
   127:  const gpsPathKm = round(pathM / 1000);
   128:
   129:  const findings: string[] = [];
   130:
   131:  if (points.length === 0) {
   132:    findings.push('No GPS points were recorded during the trip window (pickup to drop-off).');
   133:  } else {
   134:    findings.push(
   135:      `Metered distance ${trip.actual_distance_km} km vs recommended ${route.distance_km} km ` +
   136:        `(${extraKm >= 0 ? '+' : ''}${round(extraKm)} km, ${round(deviationPct)}%; policy tolerance ${tolerance}%).`
   137:    );
   138:    findings.push(
   139:      offRoute.length
   140:        ? `${offRoute.length} of ${points.length} trip GPS points are more than ${OFF_ROUTE_M} m from the recommended route ` +
   141:          `(max ${Math.round(Math.max(...offsets.map((o) => o.m)))} m).`
   142:        : `All ${points.length} trip GPS points are within ${OFF_ROUTE_M} m of the recommended route.`
   143:    );
   144:    // Flag a material discrepancy between the GPS path distance and the metered distance
   145:    if (gpsPathKm > 0 && Math.abs(gpsPathKm - trip.actual_distance_km) > Math.max(0.5, trip.actual_distance_km * 0.1)) {
   146:      findings.push(
   147:        `GPS path distance ${gpsPathKm} km differs materially from the metered distance ${trip.actual_distance_km} km, ` +
   148:        `which may indicate a metering issue or GPS gaps.`
   149:      );
   150:    }
   151:    findings.push(`Trip took ${round(actualMin)} min vs ${trip.estimated_duration_min} min estimated.`);
   152:    findings.push(...stops.map((s) => `Stationary mid-trip from ${s.from} to ${s.to} (${s.minutes} min).`));
   153:    findings.push(
   154:      `Final fare ${money(trip.final_fare)} vs upfront estimate ${money(trip.estimated_fare)} ` +
   155:        `(${fareDiff >= 0 ? '+' : ''}${money(fareDiff)}).`
   156:    );
   157:  }
   158:  if (!breakdownOk) findings.push(`Fare components add up to ${money(computedTotal)}, not the stated total ${money(fb.total)}.`);
   159:  if (!totalOk) findings.push(`Breakdown total ${money(fb.total)} differs from the charged fare ${money(trip.final_fare)}.`);
   160:  if (fb.surge_multiplier > 1) findings.push(`Surge multiplier ${fb.surge_multiplier} applied.`);
   161:  if (fb.promo_code) findings.push(`Promo code ${fb.promo_code} applied (discount ${money(fb.promo_discount)}).`);
   162:
   163:  return {
   164:    recommended_distance_km: route.distance_km,
   165:    actual_distance_km: trip.actual_distance_km,
   166:    extra_distance_km: round(extraKm),
   167:    deviation_pct: round(deviationPct),
   168:    tolerance_pct: tolerance,
   169:    exceeds_tolerance: deviationPct > tolerance,
   170:    gps_path_distance_km: gpsPathKm,
   171:    max_off_route_m: offsets.length ? Math.round(Math.max(...offsets.map((o) => o.m))) : 0,
   172:    off_route_points: offRoute.length,
   173:    first_off_route_point: offRoute[0]?.ref ?? null,
   174:    estimated_duration_min: trip.estimated_duration_min,
   175:    actual_duration_min: round(actualMin),
   176:    extra_duration_min: round(actualMin - trip.estimated_duration_min),
   177:    unexpected_stops: stops,
   178:    estimated_fare: money(trip.estimated_fare),
   179:    final_fare: money(trip.final_fare),
   180:    fare_difference: money(fareDiff),
   181:    fare_difference_pct: trip.estimated_fare > 0 ? round((fareDiff / trip.estimated_fare) * 100) : null,
   182:    breakdown_computed_total: money(computedTotal),
   183:    breakdown_matches_total: breakdownOk,
   184:    total_matches_final_fare: totalOk,
   185:    findings,
   186:  };
   187:}
