   149: "recommendation":"driver|passenger|shared|inconclusive",
   150: "recommendationReasoning":"ruling with source-grounded explanation",
   151: "suggestedActions":["specific action including amount and recipient when justified"],
   152: "confidenceScore":"integer from 0 to 100", "confidenceReasoning":"uncertainties",
   153: "sourceRefs":["/existing/source/path"], "missingEvidence":["missing facts or unresolved conflicts"],
   154: "checklist":[{"id":"C1","finding":"what the record shows","conflict":false,"sourceRefs":["/existing/source/path"]}],
